      await s.ends([
        { label: "As the story ends", ends: { tab: ["c0 +TYPED", "c1", "c2", "ONLINE CELL"], server: ["c0 +TYPED", "c1", "c2", "ONLINE CELL"], file: ["c0 +TYPED", "c1", "c2", "ONLINE CELL"] } },
      ]);
